/** UC-002: View Veterinarians, with rows fetched as the visitor scrolls. */
@Route(value = "vets", layout = MainLayout.class)
@PageTitle("Veterinarians")
public class VetsView extends VerticalLayout {

    private final transient VetRepository repository;

    public VetsView(VetRepository repository) {
        this.repository = repository;
        setSizeFull();

        H2 heading = new H2("Veterinarians");
        heading.addClassNames(LumoUtility.Margin.NONE);

        Grid<Vet> grid = new Grid<>(Vet.class, false);
        grid.setSizeFull();
        grid.setSelectionMode(Grid.SelectionMode.NONE);
        grid.getElement().setAttribute("aria-label", "Veterinarians");
        grid.addColumn(Vet::firstName).setHeader("First Name").setAutoWidth(true);
        grid.addColumn(Vet::lastName).setHeader("Last Name").setAutoWidth(true);
        grid.addColumn(vet -> vet.specialties().isEmpty()
                        ? "none" : String.join(", ", vet.specialties()))
                .setHeader("Specialties").setAutoWidth(true).setFlexGrow(2);
        grid.setDataProvider(DataProvider.fromCallbacks(
                query -> fetchPage(query.getOffset(), query.getLimit()),
                query -> count()));

        add(heading, grid);
        expand(grid);
    }

    private Stream<Vet> fetchPage(int offset, int limit) {
        try {
            return repository.findPage(offset, limit);
        } catch (DataAccessException failure) {
            showError(failure);
            return Stream.empty();
        }
    }

    private int count() {
        try {
            return repository.count();
        } catch (DataAccessException failure) {
            showError(failure);
            return 0;
        }
    }

    private void showError(DataAccessException failure) {
        // Lazy callbacks run after navigation, so the router does not catch their exceptions.
        UI ui = UI.getCurrent();
        ui.getInternals().getRouter().handleExceptionNavigation(ui,
                ui.getInternals().getActiveViewLocation(), failure,
                NavigationTrigger.PROGRAMMATIC, null);
    }
}
