+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.core.ui.ApplicationErrorView;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.sidenav.SideNavItem;
+import com.vaadin.flow.data.provider.Query;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.List;
+import java.util.stream.IntStream;
+
+import static ai.unifiedprocess.demo.petclinic.database.tables.VetSpecialties.VET_SPECIALTIES;
+import static ai.unifiedprocess.demo.petclinic.database.tables.Vets.VETS;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+/** UC-002: View Veterinarians. Database changes roll back after each test. */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void anonymousVisitorSeesNamesAndAlphabeticalSpecialties() {
+        navigate(WelcomeView.class);
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected the Veterinarians navigation item");
+        UI.getCurrent().navigate(link.getPath());
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        Grid<Vet> grid = grid();
+        assertEquals(List.of("First Name", "Last Name", "Specialties"),
+                IntStream.range(0, 3).mapToObj(i -> test(grid).getHeaderCell(i)).toList());
+        assertEquals(6, test(grid).size());
+        assertEquals(List.of("James", "Carter", "none"), rowText(grid, 0));
+        assertEquals(List.of("Linda", "Douglas", "dentistry, surgery"), rowText(grid, 1));
+        assertEquals(List.of("Helen", "Leary", "radiology"), rowText(grid, 3));
+        assertEquals(List.of("Sharon", "Jenkins", "none"), rowText(grid, 2));
+        assertEquals(6, dsl.fetchCount(VETS), "Browsing must preserve the veterinarian data");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void dataProviderFetchesBoundedPagesUntilTheEnd() {
+        // More than one default Grid page; identical names also exercise the ID tie-breaker.
+        var insert = dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME);
+        for (int i = 0; i < 125; i++) {
+            insert.values("Additional", "Veterinarian");
+        }
+        insert.execute();
+
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        assertFalse(grid.getDataProvider().isInMemory(), "The grid must fetch rows from the backend");
+        assertFalse(grid.isAllRowsVisible(), "The grid must use a scrollable viewport");
+        assertEquals(131, grid.getDataProvider().size(new Query<>()));
+
+        List<Vet> first = page(grid, 0, 50);
+        List<Vet> second = page(grid, 50, 50);
+        List<Vet> last = page(grid, 100, 50);
+        assertEquals(50, first.size());
+        assertEquals(50, second.size());
+        assertEquals(31, last.size());
+        List<Vet> all = java.util.stream.Stream.of(first, second, last).flatMap(List::stream).toList();
+        assertEquals(131, all.stream().map(Vet::id).distinct().count(), "Pages must not repeat rows");
+        assertEquals(all, page(grid, 0, 150), "Page boundaries must preserve the directory order");
+        assertTrue(page(grid, 131, 50).isEmpty());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryStillRendersTheGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetsView.class);
+
+        assertEquals(0, test(grid()).size());
+        assertTrue(page(grid(), 0, 50).isEmpty());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void dataAccessFailureReplacesTheDirectoryWithTheApplicationErrorView() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        // A real database failure, isolated by this test's rollback.
+        dsl.alterTable(VETS).renameTo("unavailable_vets").execute();
+        assertTrue(page(grid, 0, 50).isEmpty());
+
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(),
+                "Expected the application error view after a database failure");
+        assertTrue(find(Grid.class).all().isEmpty(), "No veterinarian list should remain on error");
+        assertDoesNotThrow(() -> find(Paragraph.class)
+                .withCondition(paragraph -> paragraph.getText().contains("vets")).single(),
+                "Expected the error message to be displayed");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureAlsoReplacesTheDirectoryWithTheApplicationErrorView() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        dsl.alterTable(VETS).renameTo("unavailable_vets").execute();
+
+        assertEquals(0, grid.getDataProvider().size(new Query<>()));
+
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(),
+                "Expected the application error view after a count failure");
+        assertTrue(find(Grid.class).all().isEmpty(), "No veterinarian list should remain on error");
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> grid() {
+        return (Grid<Vet>) assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected exactly one veterinarian grid");
+    }
+
+    private List<String> rowText(Grid<Vet> grid, int row) {
+        return IntStream.range(0, 3).mapToObj(column -> test(grid).getCellText(row, column)).toList();
+    }
+
+    private List<Vet> page(Grid<Vet> grid, int offset, int limit) {
+        return grid.getDataProvider().fetch(new Query<>(offset, limit, List.of(), null, null)).toList();
+    }
+}
